INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1443589-mkt399', 'stk-user8581', 'MKT 399', 'info', '{"desc": "(( هذا البرنامج للأسف فيه رسوم وانا ضد هذا الشي لكن يمكن فيه غيري يشوف هالشي عادي فنزلت اعلان عنه ))\nلا تعطوني ديس لايك 😐\n\nالبرنامج الصيفي للمهارات الهندسية والفنية لطلاب الهندسة\nhttp://cecs.rcyci.edu.sa/cers/img/ad-summer2016\n\nsummereng.ml\nخطة التدريب\nSTProgram-CECS.pdf - Google Drive\n\nالبرنامج الصيفي المهارات الفنية لطلاب الهندسة بالجامعات السعودية\nتعريف البرنامج : هو برنامج محاكاة العمل الفني والهندسي لابرز المنشآت الصناعية و شركات توليد الطاقة وهو معتبر بمادة التدريب الصيفي بالجامعات السعودية وغيرهاالهدف من البرنامج : برنامج تدريبي يركز على تنمية أبرز المهارات الفنية والتقنية للمهندسين والتي تطلبها طبيعة العمل في القطاع الصناعيالفئة المستهدفة : طلاب تخصص الهندسة الميكانيكية والكهربائية و الصناعية طريقة التدريب : التدريب بطريقة ادارة المشاريععدد ساعات التدريب : 280 ساعة تدريبية يشملها شهادة معتمدةمميزات البرنامج :\n1- محاكاة العمل الهندسي لابرز المنشآت الصناعية ومحطات توليد الطاقة\n2- ( 11) دورات تدريبية بواقع 20 ساعة تدريبية لكل دورة يشملها شهادة معتمدة لكل دورة\n3- زيارات لابرز الشركات و المنشآت الصناعية بمدينة ينبع الصناعية\n4- سكن خاص لكل متدرب خلال فترة التدريب\n5- برنامج تدريبي للغة الانكليزية بواقع 60 ساعة يشملها شهادة معتمدة\n6- تقرير معتمد من المعهد التقني بكليات ينبع الصناعية بأن التدريب وفق معايير ابرز الشركات و المنشآت الصناعية\n7- معرض للمشاريع المنفذة خلال فترة البرنامج ودعوة ابرز الشركات والمنشآت الصناعية\n8- برامج ترفيهية وثقافية وواجهة بحرية خلابة\n(التدريب الصيفي)مدة البرنامج :\nشهرين\n8 اسابيع تدريبية\nبداية البرنامج يوم الاثنين تاريخ 6/10/1437 الموافق 11/7/2016\nنهاية البرنامج يوم الخميس تاريخ 29/11/1437 الموافق 1/9/2016***رسوم الاشتراك بالبرنامج : التسجيل المبكر : 6500 ريال سعودي حتى نهاية تاريخ 26/6/1437 الموافق 4/4/2016\nالتسجيل المتأخر : 7000 ريال سعودي حتى نهاية تاريخ 29/8/1437 الموافق 5/5/2016لمعرفة تفاصيل سداد الرسوم الرجاء ارسال للايميل التالي:\namallcom.co@gmail.comللتواصل جوال أو واتس اب : 0544085566\n\nالجهة المنفذة للبرنامج\n\nhttps://lh5.googleusercontent.com/9WgGTAXFjl-lKxVaBuIS6DJYzmiXMZoMOPbsrCiMXN2OwVv2nd53z2ypyIA44LY3b0yVgw\n\nلمشاهدة البرنامج الصيفي للمهارات الهندسية والفنية لطلاب الهندسة :http://cecs.rcyci.edu.sa/cers/index\n\nhttps://lh4.googleusercontent.com/DFxh24ZUihJ9otHafCOSMHgjOa7-HiBRKndgGAF2VtqX-R14dof_JD_hNUCadIBkTy8wKA\n\nالشريك التسويقي “أعمالكم”\n\nhttps://lh4.googleusercontent.com/YIwa9LrNtfT3bkX88gw_FGIkszfxTmEjcM8-Hs37KBNcgB_TUZHpxnx--uz7qOMcmin58Q", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/161-152-153/170272/101", "user": "user8581", "ts": 1456944878000, "tid": 170272, "pn": 101}}', 1456944878000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
